solution.solution.cpp:
#include <string_view>
#include <vector>

template <typename T>
struct TypeName
{
    static constexpr std::string_view value{ "other" };
};

template <>
struct TypeName<int>
{
    static constexpr std::string_view value{ "int" };
};

template <>
struct TypeName<double>
{
    static constexpr std::string_view value{ "double" };
};

template <typename U>
struct TypeName<U*>
{
    static constexpr std::string_view value{ "pointer" };
};

template <typename U>
struct TypeName<std::vector<U>>
{
    static constexpr std::string_view value{ "vector" };
};

template <typename T>
struct IsPointer
{
    static constexpr bool value{ false };
};

template <typename U>
struct IsPointer<U*>
{
    static constexpr bool value{ true };
};

unitTests:
static_assert(TypeName<int>::value == "int");
static_assert(TypeName<double>::value == "double");
static_assert(TypeName<int*>::value == "pointer");
static_assert(TypeName<const char*>::value == "pointer");
static_assert(TypeName<std::vector<int>>::value == "vector");
static_assert(TypeName<std::vector<std::vector<double>>>::value == "vector");
static_assert(TypeName<char>::value == "other");
static_assert(IsPointer<int*>::value && IsPointer<void*>::value && IsPointer<double**>::value);
static_assert(!IsPointer<int>::value && !IsPointer<std::vector<int*>>::value);

TEST("usable at run time as well") { CHECK_EQ(TypeName<float>::value, "other"); CHECK_EQ(TypeName<float*>::value, "pointer"); CHECK(IsPointer<char*>::value); }

